81	
82	export function applyReplacement(
83	  currentContent: string | null,
84	  oldString: string,
85	  newString: string,
86	  isNewFile: boolean,
87	): string {
88	  if (isNewFile) {
89	    return newString;
90	  }
91	  if (currentContent === null) {
92	    // Should not happen if not a new file, but defensively return empty or newString if oldString is also empty
93	    return oldString === '' ? newString : '';
94	  }
95	  // If oldString is empty and it's not a new file, do not modify the content.
96	  if (oldString === '' && !isNewFile) {
97	    return currentContent;
98	  }
99	
100	  // Use intelligent replacement that handles $ sequences safely
101	  return safeLiteralReplace(currentContent, oldString, newString);
102	}
