104	/**
105	 * Creates a SHA256 hash of the given content.
106	 * @param content The string content to hash.
107	 * @returns A hex-encoded hash string.
108	 */
109	function hashContent(content: string): string {
110	  return crypto.createHash('sha256').update(content).digest('hex');
111	}
