113	function restoreTrailingNewline(
114	  originalContent: string,
115	  modifiedContent: string,
116	): string {
117	  const hadTrailingNewline = originalContent.endsWith('\n');
118	  if (hadTrailingNewline && !modifiedContent.endsWith('\n')) {
119	    return modifiedContent + '\n';
120	  } else if (!hadTrailingNewline && modifiedContent.endsWith('\n')) {
121	    return modifiedContent.replace(/\n$/, '');
122	  }
123	  return modifiedContent;
124	}
