126	/**
127	 * Escapes characters with special meaning in regular expressions.
128	 * @param str The string to escape.
129	 * @returns The escaped string.
130	 */
131	function escapeRegex(str: string): string {
132	  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // $& means the whole matched string
133	}
