135	async function calculateExactReplacement(
136	  context: ReplacementContext,
137	): Promise<ReplacementResult | null> {
138	  const { currentContent, params } = context;
139	  const { old_string, new_string } = params;
140	
141	  const normalizedCode = currentContent;
142	  const normalizedSearch = old_string.replace(/\r\n/g, '\n');
143	  const normalizedReplace = new_string.replace(/\r\n/g, '\n');
144	
145	  const exactOccurrences = normalizedCode.split(normalizedSearch).length - 1;
146	
147	  if (!params.allow_multiple && exactOccurrences > 1) {
148	    return {
149	      newContent: currentContent,
150	      occurrences: exactOccurrences,
151	      finalOldString: normalizedSearch,
152	      finalNewString: normalizedReplace,
153	    };
154	  }
155	
156	  if (exactOccurrences > 0) {
157	    let modifiedCode = safeLiteralReplace(
158	      normalizedCode,
159	      normalizedSearch,
160	      normalizedReplace,
161	    );
162	    modifiedCode = restoreTrailingNewline(currentContent, modifiedCode);
163	    return {
164	      newContent: modifiedCode,
165	      occurrences: exactOccurrences,
166	      finalOldString: normalizedSearch,
167	      finalNewString: normalizedReplace,
168	    };
169	  }
170	
171	  return null;
172	}
