174	async function calculateFlexibleReplacement(
175	  context: ReplacementContext,
176	): Promise<ReplacementResult | null> {
177	  const { currentContent, params } = context;
178	  const { old_string, new_string } = params;
179	
180	  const normalizedCode = currentContent;
181	  const normalizedSearch = old_string.replace(/\r\n/g, '\n');
182	  const normalizedReplace = new_string.replace(/\r\n/g, '\n');
183	
184	  const sourceLines = normalizedCode.match(/.*(?:\n|$)/g)?.slice(0, -1) ?? [];
185	  const searchLinesStripped = normalizedSearch
186	    .split('\n')
187	    .map((line: string) => line.trim());
188	  const replaceLines = normalizedReplace.split('\n');
189	
190	  let flexibleOccurrences = 0;
191	  let i = 0;
192	  while (i <= sourceLines.length - searchLinesStripped.length) {
193	    const window = sourceLines.slice(i, i + searchLinesStripped.length);
194	    const windowStripped = window.map((line: string) => line.trim());
195	    const isMatch = windowStripped.every(
