11	/**
12	 * Standard error messages for the plan approval workflow.
13	 * Shared between backend tools and CLI UI for consistency.
14	 */
15	export const PlanErrorMessages = {
16	  PATH_ACCESS_DENIED: (planPath: string, plansDir: string) =>
17	    `Access denied: plan path (${planPath}) must be within the designated plans directory (${plansDir}).`,
18	  FILE_NOT_FOUND: (path: string) =>
19	    `Plan file does not exist: ${path}. You must create the plan file before requesting approval.`,
20	  FILE_EMPTY:
21	    'Plan file is empty. You must write content to the plan file before requesting approval.',
22	  READ_FAILURE: (detail: string) => `Failed to read plan file: ${detail}`,
23	} as const;
24	
25	/**
26	 * Resolves a plan file path and strictly validates it against the plans directory boundary.
27	 * Useful for tools that need to write or read plans.
28	 * @param planPath The untrusted file path provided by the model.
29	 * @param plansDir The authorized project plans directory.
30	 * @returns The safely resolved path string.
31	 * @throws Error if the path is empty, malicious, or escapes boundaries.
32	 */
33	export function resolveAndValidatePlanPath(
34	  planPath: string,
35	  plansDir: string,
36	  projectRoot: string,
37	): string {
38	  const trimmedPath = planPath.trim();
39	  if (!trimmedPath) {
40	    throw new Error('Plan file path must be non-empty.');
41	  }
42	
43	  // 1. Handle case where agent provided an absolute path
44	  if (path.isAbsolute(trimmedPath)) {
45	    if (
46	      isSubpath(resolveToRealPath(plansDir), resolveToRealPath(trimmedPath))
47	    ) {
48	      return trimmedPath;
49	    }
50	  }
51	
52	  // 2. Handle case where agent provided a path relative to the project root
53	  const resolvedFromProjectRoot = path.resolve(projectRoot, trimmedPath);
54	  if (
55	    isSubpath(
56	      resolveToRealPath(plansDir),
57	      resolveToRealPath(resolvedFromProjectRoot),
58	    )
59	  ) {
60	    return resolvedFromProjectRoot;
61	  }
62	
63	  // 3. Handle default case where agent provided a path relative to the plans directory
64	  const resolvedPath = path.resolve(plansDir, trimmedPath);
65	  const realPath = resolveToRealPath(resolvedPath);
66	  const realPlansDir = resolveToRealPath(plansDir);
67	
68	  if (!isSubpath(realPlansDir, realPath)) {
69	    throw new Error(
70	      PlanErrorMessages.PATH_ACCESS_DENIED(trimmedPath, plansDir),
71	    );
72	  }
73	
74	  return resolvedPath;
75	}
76	
77	/**
78	 * Validates a plan file path for safety (traversal) and existence.
79	 * @param planPath The untrusted path to the plan file.
80	 * @param plansDir The authorized project plans directory.
81	 * @param projectRoot The root directory of the project.
82	 * @returns An error message if validation fails, or null if successful.
83	 */
84	export async function validatePlanPath(
85	  planPath: string,
86	  plansDir: string,
87	  projectRoot: string,
88	): Promise<string | null> {
89	  try {
90	    const resolvedPath = resolveAndValidatePlanPath(
91	      planPath,
92	      plansDir,
93	      projectRoot,
94	    );
95	    if (!(await fileExists(resolvedPath))) {
96	      return PlanErrorMessages.FILE_NOT_FOUND(planPath);
97	    }
98	    return null;
99	  } catch {
100	    return PlanErrorMessages.PATH_ACCESS_DENIED(
101	      planPath,
102	      resolveToRealPath(plansDir),
103	    );
104	  }
105	}
106	
107	/**
108	 * Validates that a plan file has non-empty content.
109	 * @param planPath The path to the plan file.
110	 * @returns An error message if the file is empty or unreadable, or null if successful.
111	 */
112	export async function validatePlanContent(
113	  planPath: string,
114	): Promise<string | null> {
115	  try {
116	    if (await isEmpty(planPath)) {
117	      return PlanErrorMessages.FILE_EMPTY;
118	    }
119	    return null;
120	  } catch (err) {
121	    const message = err instanceof Error ? err.message : String(err);
122	    return PlanErrorMessages.READ_FAILURE(message);
123	  }
124	}
