/**
 * Returns true if the first path segment of `relativePath` exists inside any of
 * the workspace directories.
 */
function firstSegmentExistsInWorkspace(
  relativePath: string,
  config: Config,
): boolean {
  const firstSegment = relativePath.split(/[/\\]/).filter(Boolean)[0];
  if (!firstSegment) {
    return false;
  }

  const searchDirs = config.getWorkspaceContext().getDirectories();
  return searchDirs.some((dir) => {
    try {
      return fs.existsSync(path.join(dir, firstSegment));
    } catch {
      return false;
    }
  });
}

/**
 * Defensively strips a leading at-sign (`@`) from a file path.
 *
 * The `@` prefix is used by the CLI's at-command syntax to reference files.
 * Models occasionally include this prefix in tool arguments, which would
 * otherwise cause the tool to operate on a literal `@`-prefixed path.
 *
 * Stripping rules:
 *   - `@/foo` or `@\foo` (an at-sign immediately followed by a path separator)
 *     always has the prefix stripped.
 *   - `@foo/bar` (an at-sign followed by a segment, with no leading separator)
 *     only has the prefix stripped when the first path segment (`foo`) exists
 *     within the workspace. This avoids clobbering a real file or directory
 *     that is legitimately named with a leading `@`.
 *
 * @param filePath The raw file path provided by the model.
 * @param config The application configuration.
 * @returns The path with the `@` prefix stripped when appropriate, otherwise
 *   the original path unchanged.
 */
export function stripAtPrefix(filePath: string, config: Config): string {
  if (!filePath.startsWith('@')) {
    return filePath;
  }

  const withoutPrefix = filePath.slice(1);
  if (withoutPrefix === '') {
    return filePath;
  }

  // `@/...` or `@\...` -> always strip the prefix.
  if (withoutPrefix.startsWith('/') || withoutPrefix.startsWith('\\')) {
    return withoutPrefix;
  }

  // `@segment/...` -> only strip when the first segment exists in the workspace.
  if (firstSegmentExistsInWorkspace(withoutPrefix, config)) {
    return withoutPrefix;
  }

  return filePath;
}

